package android.os;import java.util.*;public class Bundle {public final Map<String,Object> data=new HashMap<String,Object>(); public int getInt(String k,int d){Object v=data.get(k);return v instanceof Number?((Number)v).intValue():d;}public void putInt(String k,int v){data.put(k,v);}public <T> ArrayList<T> getParcelableArrayList(String k){return (ArrayList<T>)data.get(k);}public void putParcelableArrayList(String k,ArrayList v){data.put(k,v);}}
